package ring

type Buf struct {
	data []int
	cap  int
}

func New(n int) *Buf {
	return &Buf{cap: n}
}

// Push keeps at most cap items.
func (b *Buf) Push(x int) {
	if len(b.data) > b.cap {
		b.data = b.data[1:]
	}
	b.data = append(b.data, x)
}

func (b *Buf) Len() int {
	return len(b.data)
}

